CREATE COLUMN TABLE "TEST_AP"."OSGP" ("AbsEntry" INTEGER CS_INT NOT NULL , "ServiceGrp" NVARCHAR(3) NOT NULL , "Descrip" NVARCHAR(70), "LogInstanc" INTEGER CS_INT DEFAULT 0, "UserSign2" SMALLINT CS_INT, "UpdateDate" LONGDATE CS_LONGDATE, PRIMARY KEY ("AbsEntry")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OSGP_CODE" ON "TEST_AP"."OSGP" ( "ServiceGrp" ASC )